public class RecursiveStringTools {
    static String reverse(String text) {
        requireText(text);
        StringBuilder result = new StringBuilder(text.length());
        appendReverse(text, text.length() - 1, result);
        return result.toString();
    }

    private static void appendReverse(String text, int index, StringBuilder result) {
        if (index < 0) return;
        result.append(text.charAt(index));
        appendReverse(text, index - 1, result);
    }

    static boolean isPalindrome(String text) {
        requireText(text);
        return isPalindrome(text, 0, text.length() - 1);
    }

    private static boolean isPalindrome(String text, int left, int right) {
        if (left >= right) return true;
        if (text.charAt(left) != text.charAt(right)) return false;
        return isPalindrome(text, left + 1, right - 1);
    }

    private static void requireText(String text) {
        if (text == null) throw new IllegalArgumentException("text cannot be null");
    }

    static void expect(Class<? extends Throwable> type, Runnable action) {
        try {
            action.run();
        } catch (Throwable error) {
            if (type.isInstance(error)) return;
            throw error;
        }
        throw new AssertionError("expected " + type.getSimpleName());
    }

    public static void main(String[] args) {
        assert reverse("abcd").equals("dcba");
        assert reverse("").equals("");
        assert reverse("中").equals("中");
        assert isPalindrome("");
        assert isPalindrome("a");
        assert isPalindrome("level");
        assert isPalindrome("上海自来水来自海上");
        assert !isPalindrome("java");
        expect(IllegalArgumentException.class, () -> reverse(null));
        expect(IllegalArgumentException.class, () -> isPalindrome(null));
        System.out.println("recursive-string checks: OK");
    }
}
